// Why Code: suma costului de azi (UTC, ca plafonul din aplicație), comparația cu pragurile și memoria „am anunțat deja azi”
// (static data a workflow-ului), ca alerta să plece o singură dată pe zi pentru fiecare prag; niciun nod nativ nu ține starea între rulări.
let rows = [];
try { rows = JSON.parse($input.first().json.data || '[]'); } catch { rows = []; }
if (!Array.isArray(rows)) throw new Error('Răspuns neașteptat de la ai_calls');

// Același plafon ca în aplicație (AI_DAILY_BUDGET_USD, implicit 5 USD). La 100%, aplicația oprește singură citirea actelor.
const budget = Number($env.AI_DAILY_BUDGET_USD) > 0 ? Number($env.AI_DAILY_BUDGET_USD) : 5;
const spent = rows.reduce((s, r) => s + (Number(r.cost_usd) || 0), 0);
const failed = rows.filter((r) => r.success === false).length;
const share = spent / budget;
const level = share >= 1 ? 100 : share >= 0.8 ? 80 : 0;
if (!level) return [];

const today = $now.toUTC().toISODate();
const state = $getWorkflowStaticData('global');
if (state.day !== today) { state.day = today; state.sent = []; }
if (state.sent.includes(level)) return [];
state.sent.push(level);

const usd = (v) => '$' + v.toFixed(2);
const text = [
  level === 100 ? '🛑 Plafonul zilnic AI a fost atins' : '⚠️ Costul AI de azi a trecut de 80% din plafon',
  `Azi (UTC): ${usd(spent)} din ${usd(budget)} (${Math.round(share * 100)}%), ${rows.length} apeluri, ${failed} eșuate.`,
  level === 100 ? 'Citirea actelor din wizard e oprită până mâine; vocea nu e oprită de plafon.' : 'La 100%, citirea actelor din wizard se oprește până mâine.',
  'Detalii: /broker/costuri',
].join('\n');

const chats = String($env.TG_BROKER_CHAT_IDS ?? '').split(',').map((x) => x.trim()).filter(Boolean);
if (!chats.length) throw new Error('TG_BROKER_CHAT_IDS lipsește din mediul n8n: alerta nu are destinatar.');
return chats.map((chatId) => ({ json: { chatId, text } }));
